From 73021d1ddcc6f847d7cf85ecba75ef5cf4dff827 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 22:49:11 +0100
Subject: [PATCH] applets/taskmanager: add a menu to choose an app's audio
 output device

The context menu of a task playing audio only offered muting it, so moving
an app to other speakers or headphones meant opening the audio applet. Add
a "Play Audio Using" submenu next to Mute that lists the output devices.

BUG: 445149
---
 applets/taskmanager/qml/ContextMenu.qml | 45 +++++++++++++++++++++++++
 applets/taskmanager/qml/PulseAudio.qml  | 10 ++++++
 2 files changed, 55 insertions(+)

diff --git a/applets/taskmanager/qml/ContextMenu.qml b/applets/taskmanager/qml/ContextMenu.qml
index fe837049fc..3d1a3cbf84 100644
--- a/applets/taskmanager/qml/ContextMenu.qml
+++ b/applets/taskmanager/qml/ContextMenu.qml
@@ -267,10 +267,55 @@ PlasmaExtras.Menu {
             muteItem.icon = "audio-volume-muted" + (Application.layoutDirection === Qt.RightToLeft ? "-rtl" : "");
             menu.addMenuItem(muteItem, startNewInstanceItem);

+            menu.addMenuItem(audioDevicesMenuItem, startNewInstanceItem);
+
             menu.addMenuItem(newSeparator(menu), startNewInstanceItem);
         }
     }

+    PlasmaExtras.MenuItem {
+        id: audioDevicesMenuItem
+
+        visible: ((menu.visualParent as Task)?.hasAudioStream ?? false) && audioDevicesInstantiator.count > 1
+        enabled: visible
+
+        text: i18nc("@action:inmenu", "Play Audio Using")
+        icon: "audio-card"
+
+        readonly property PlasmaCore.ActionGroup _audioDevicesActionGroup: PlasmaCore.ActionGroup {
+            id: audioDevicesActionGroup
+        }
+
+        readonly property PlasmaExtras.Menu _audioDevicesMenu: PlasmaExtras.Menu {
+            id: audioDevicesMenu
+            visualParent: audioDevicesMenuItem.action
+        }
+
+        readonly property Instantiator _audioDevicesInstantiator: Instantiator {
+            id: audioDevicesInstantiator
+
+            model: pulseAudio.item?.sinks ?? null
+
+            delegate: PlasmaExtras.MenuItem {
+                id: audioDeviceMenuItem
+                required property var model
+
+                parent: audioDevicesMenu
+                action: PlasmaCore.Action {
+                    text: audioDeviceMenuItem.model.Description
+                    actionGroup: audioDevicesActionGroup
+                    checkable: true
+                }
+
+                checked: (menu.visualParent as Task)?.audioStreams.every(stream => stream.deviceIndex === audioDeviceMenuItem.model.Index) ?? false
+
+                onClicked: {
+                    (menu.visualParent as Task).audioStreams.forEach(stream => stream.setDeviceIndex(audioDeviceMenuItem.model.Index));
+                }
+            }
+        }
+    }
+
     PlasmaExtras.MenuItem {
         id: startNewInstanceItem
         visible: menu.get(TaskManager.AbstractTasksModel.CanLaunchNewInstance)
diff --git a/applets/taskmanager/qml/PulseAudio.qml b/applets/taskmanager/qml/PulseAudio.qml
index bbafcd8d0f..2dcbc6fbf1 100644
--- a/applets/taskmanager/qml/PulseAudio.qml
+++ b/applets/taskmanager/qml/PulseAudio.qml
@@ -101,6 +101,7 @@ QtObject {
             // whether there is nothing actually going on on that stream
             readonly property bool corked: model.Corked
             readonly property int volume: model.Volume
+            readonly property int deviceIndex: model.DeviceIndex

             function mute(): void {
                 model.Muted = true;
@@ -108,6 +109,9 @@ QtObject {
             function unmute(): void {
                 model.Muted = false;
             }
+            function setDeviceIndex(index: int): void {
+                model.DeviceIndex = index;
+            }
         }

         delegate: StreamDelegate { }
@@ -116,6 +120,12 @@ QtObject {
         onObjectRemoved: (index, object) => pulseAudio.streamsChanged()
     }

+    readonly property PlasmaPa.PulseObjectFilterModel sinks: PlasmaPa.PulseObjectFilterModel {
+        filterOutInactiveDevices: true
+        filterVirtualDevices: true
+        sourceModel: PlasmaPa.SinkModel {}
+    }
+
     readonly property int minimalVolume: PlasmaPa.PulseAudio.MinimalVolume
     readonly property int normalVolume: PlasmaPa.PulseAudio.NormalVolume
 }
-- 
